    const event = new Event({
        name: req.body.name,
        date: req.body.date,
        location: req.body.location,
        description: req.body.description
    });

    event.save()
        .then(data => {
            io.emit('event:new', data);
            res.send(data);
        })
        .catch(err => {
            res.status(500).send(err);
        });
});

// Update event
