Before running the program, ensure you have Java 11 or newer installed. This program doesn't handle API authentication or rate limiting, so it's intended for educational purposes and should be used with caution to respect Stack Overflow's API usage policies.

```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import org.json.JSONArray;
import org.json.JSONObject;

public class StackOverflowAPI {

    private static final String API_URL = "https://api.stackexchange.com/2.3/questions?order=desc&sort=activity&tagged=python&site=stackoverflow";

    public static void main(String[] args) {
        try {
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(API_URL))
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

            JSONObject jsonResponse = new JSONObject(response.body());
            JSONArray questions = jsonResponse.getJSONArray("items");

            for (int i = 0; i < questions.length(); i++) {
                JSONObject question = questions.getJSONObject(i);
                System.out.println("Question: " + question.getString("title"));
                System.out.println("Link: " + question.getString("link"));

                // Fetching answers for the question
                if (!question.getBoolean("is_answered")) {
                    System.out.println("This question has no answers yet.\n");
                    continue;
                }

                String answersUrl = "https://api.stackexchange.com/2.3/questions/" + question.getInt("question_id") + "/answers?order=desc&sort=activity&site=stackoverflow";
                HttpRequest answersRequest = HttpRequest.newBuilder()
                        .uri(URI.create(answersUrl))
                        .build();

                HttpResponse<String> answersResponse = client.send(answersRequest, HttpResponse.BodyHandlers.ofString());
                JSONObject jsonAnswersResponse = new JSONObject(answersResponse.body());
                JSONArray answers = jsonAnswersResponse.getJSONArray("items");

                for (int j = 0; j < answers.length(); j++) {
                    JSONObject answer = answers.getJSONObject(j);
                    System.out.println("Answer ID: " + answer.getInt("answer_id"));
                    // More fields can be added as needed
                }
                System.out.println();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

