def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5)+1):
        if num % i == 0:
            return False
    return True

def replace_composites(lst):
    new_lst = []
    for num in lst:
        if is_prime(num):
            new_lst.append(num)
        else:
            while True:
                next_prime = find_next_prime(num)
                if next_prime not in new_lst:
