Here is how you can implement such a class in Python:

```python
class SingletonMeta(type):
    """
    This is a metaclass that creates a Singleton base class when called.
    """
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            instance = super().__call__(*args, **kwargs)
            cls._instances[cls] = instance
        return cls._instances[cls]

class Material(metaclass=SingletonMeta):
    def __init__(self):
        self.shape = None
        self.texture = None
        self.density = None

    def set_shape(self, shape):
        if not isinstance(shape, str):
            raise ValueError("Shape must be a string.")
        self.shape = shape

    def set_texture(self, texture):
        if not isinstance(texture, str):
            raise ValueError("Texture must be a string.")
        self.texture = texture

    def set_density(self, density):
        if not isinstance(density, (int, float)):
            raise ValueError("Density must be an integer or float.")
        self.density = density

    def is_density_in_range(self, min_density, max_density):
        if self.density is None:
            raise ValueError("Density has not been set.")
        return min_density <= self.density <= max_density

# Example usage:
