    material.set_shape("Cube")
    material.set_texture("Rough")
    material.set_density(5.5)
    print(f"Shape: {material.shape}, Texture: {material.texture}, Density: {material.density}")
    print("Density is within range (5, 6):", material.is_density_in_range(5, 6))
