console.log(calculateIsoscelesTrapezoidArea(-1, 10, 15, 15)); // Invalid input: negative number
console.log(calculateIsoscelesTrapezoidArea(8, 8, 8, 8)); // Invalid: not an isosceles trapezoid
```

