import requests
from collections import Counter

class GithubAnalysis:
    def __init__(self, url):
        self.url = url
        self.session = requests.Session()
        self.rate_limit_remaining = None

    def _fetch_data(self, url):
        response = self.session.get(url)
        self.rate_limit_remaining = int(response.headers['X-RateLimit-Remaining'])
        if response.status_code != 200:
            raise Exception("Failed to fetch data: {}".format(response.status_code))
        return response.json()

    def find_user_with_most_followers(self, users):
        return max(users, key=lambda user: user['followers'])

    def find_user_with_most_commits(self, users):
        most_commits_user = None
        most_commits = 0
        for user in users:
            commits_url = user['repos_url'].split('{')[0]
            commits = self._fetch_data(commits_url)
            commit_count = sum([c['total'] for c in commits])
            if commit_count > most_commits:
                most_commits = commit_count
                most_commits_user = user
        return most_commits_user

    def find_user_in_most_orgs(self, users):
        return max(users, key=lambda user: len(self._fetch_data(user['organizations_url'])))

    def popular_languages(self, users):
        language_counter = Counter()
        for user in users:
            repos_url = user['repos_url'].split('{')[0]
            repos = self._fetch_data(repos_url)
            for repo in repos:
                languages_url = repo['languages_url']
                languages = self._fetch_data(languages_url)
                language_counter.update(languages.keys())
        return language_counter

    def analyze(self, num_pages=1):
        users = []
        for i in range(num_pages):
            response = self._fetch_data(self.url + '?page={}'.format(i+1))
            users += response
            if self.rate_limit_remaining == 0:
                print("Rate limit reached!")
                break
        results = {
            'user_most_followers': self.find_user_with_most_followers(users),
            'user_most_commits': self.find_user_with_most_commits(users),
            'user_most_orgs': self.find_user_in_most_orgs(users),
            'popular_languages': self.popular_languages(users)}
        return results

