```cpp
template <typename T>
void quicksort(deque<T>& queue) {
    // Choose a pivot element from the deque
    T pivot = queue.front();
    queue.pop_front();

    // Partition the deque into two sub-deques
    deque<T> less(queue.begin(), queue.end());
    deque<T> greater(queue.begin(), queue.end());

