	for i := 0; i < len(str)/2; i++ {
		if str[i] != str[len(str)-1-i] {
			return false
		}
	}
	return true
}

func makePalindrome(str string) string {
	// Construct the shortest palindrome which starts with the input string
	// Approach:
	// - Discover the longest palindromic postfix in the input string
	// - Append the reverse of the non-palindromic prefix to the string's end
	longestPalindrome := ""
	for i := len(str) - 1; i >= 0; i-- {
		if isPalindrome(str[i:]) {
			longestPalindrome = str[i:]
			break
		}
	}
	reversePrefix := reverseString(str[:len(str)-len(longestPalindrome)])
	return str + reversePrefix
}

func reverseString(str string) string {
	// Reverse a string
	runes := []rune(str)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

