class Solution {
    public List<Integer> mergeSort(List<Integer> array) {
        // Check if the array is empty or has only one element
        if (array.size() <= 1) {
            return array;
        }

        // Split the array into two halves
        List<Integer> left = array.subList(0, array.size() / 2);
        List<Integer> right = array.subList(array.size() / 2, array.size());

        // Recursively sort the left and right halves
        List<Integer> leftSorted = mergeSort(left);
        List<Integer> rightSorted = mergeSort(right);

        // Merge the sorted halves
        return merge(leftSorted, rightSorted);
    }

    private List<Integer> merge(List<Integer> left, List<Integer> right) {
        // Check if either list is empty
        if (left.isEmpty() || right.isEmpty()) {
            return left;
        }

        // Create a new list to store the merged elements
        List<Integer> merged = new ArrayList<>();

        // Merge the lists
        int leftIndex = 0;
        int rightIndex = 0;
        while (leftIndex < left.size() && rightIndex < right.size()) {
            if (left.get(leftIndex) <= right.get(rightIndex)) {
                merged.add(left.get(leftIndex));
                leftIndex++;
            } else {
                merged.add(right.get(rightIndex));
                rightIndex++;
            }
        }

        // Add any remaining elements from the left or right lists
        merged.addAll(left.subList(leftIndex, left.size()));
        merged.addAll(right.subList(rightIndex, right.size()));

