```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Node structure
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Function to reverse a linked list iteratively
Node* reverseIterative(Node* head) {
    Node *prev = NULL, *current = head, *next = NULL;
    while (current != NULL) {
        next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    return prev;
}

// Function to reverse a linked list recursively
Node* reverseRecursive(Node* head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }
    Node* rest = reverseRecursive(head->next);
    head->next->next = head;
    head->next = NULL;
    return rest;
}

// Function to generate a linked list of given size
Node* generateList(int size) {
    Node* head = NULL;
    for (int i = 1; i <= size; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = i;
        newNode->next = head;
        head = newNode;
    }
    return head;
}

// Function to free the memory allocated for the linked list
void freeList(Node* head) {
    Node* current = head;
    Node* next = NULL;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

// Function to carry out stress test and compare performances
void stressTest(int size) {
    Node* head = generateList(size);

    clock_t start, end;

    start = clock();
    Node* reversedIterative = reverseIterative(head);
    end = clock();
    double timeIterative = ((double)(end - start)) / CLOCKS_PER_SEC;

    freeList(reversedIterative);

    head = generateList(size);

    start = clock();
    Node* reversedRecursive = reverseRecursive(head);
    end = clock();
    double timeRecursive = ((double)(end - start)) / CLOCKS_PER_SEC;

    freeList(reversedRecursive);

    printf("Performance comparison for a linked list of size %d:\n", size);
    printf("Iterative method took %f seconds\n", timeIterative);
    printf("Recursive method took %f seconds\n", timeRecursive);
}

int main() {
    int size = 5000; // Change the size of the linked list here
    stressTest(size);

    return 0;
}
```

