Here is a Python solution to convert the infix notation to postfix notation:

```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def is_empty(self):
        return not bool(self.items)

def infix_to_postfix(infix):
    precedence = {'+':1, '-':1, '*':2, '/':2}
    stack = Stack()
    postfix = ''
    tokens = [i for i in infix]

    for token in tokens:
        if token in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' or token in '0123456789':
            postfix += token
        elif token == '(':
            stack.push(token)
        elif token == ')':
            top_token = stack.pop()
            while top_token != '(':
                postfix += top_token
                top_token = stack.pop()
        else:
            while (not stack.is_empty()) and \
               (precedence[stack.items[-1]] >= precedence[token]):
                  postfix += stack.pop()
            stack.push(token)

    while not stack.is_empty():
        postfix += stack.pop()

    return postfix

print(infix_to_postfix("A + B * ( C - D )"))
```

When you run this script, it will print the postfix notation of the given infix expression. In this case, "A + B * ( C - D )" will be converted to "ABCD-*" which is the postfix notation of the given infix expression.

