Here is a simple implementation of a Quaternion class in Python:

```python
class Quaternion:
    def __init__(self, x=0, y=0, z=0, w=0):
        self.x = x
        self.y = y
        self.z = z
        self.w = w

    def __add__(self, other):
        if isinstance(other, Quaternion):
            return Quaternion(self.x + other.x, self.y + other.y, self.z + other.z, self.w + other.w)
        else:
            raise TypeError("Unsupported operand type(s) for +: 'Quaternion' and '{}'".format(type(other).__name__))

    def __sub__(self, other):
        if isinstance(other, Quaternion):
            return Quaternion(self.x - other.x, self.y - other.y, self.z - other.z, self.w - other.w)
        else:
            raise TypeError("Unsupported operand type(s) for -: 'Quaternion' and '{}'".format(type(other).__name__))

    def __mul__(self, other):
        if isinstance(other, Quaternion):
            x = self.w * other.x + self.x * other.w + self.y * other.z - self.z * other.y
            y = self.w * other.y - self.x * other.z + self.y * other.w + self.z * other.x
            z = self.w * other.z + self.x * other.y - self.y * other.x + self.z * other.w
            w = self.w * other.w - self.x * other.x - self.y * other.y - self.z * other.z
            return Quaternion(x, y, z, w)
        else:
            raise TypeError("Unsupported operand type(s) for *: 'Quaternion' and '{}'".format(type(other).__name__))

    def conjugate(self):
        return Quaternion(-self.x, -self.y, -self.z, self.w)

    def modulus(self):
        return (self.x ** 2 + self.y ** 2 + self.z ** 2 + self.w ** 2) ** 0.5

    def inverse(self):
        mod = self.modulus()
        if mod == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        return Quaternion(-self.x / mod, -self.y / mod, -self.z / mod, self.w / mod)

    def __str__(self):
