In Python, the Huffman coding algorithm can be implemented as follows:

```python
import heapq
import os
from collections import defaultdict

def calculate_frequency(data):
    frequency = defaultdict(int)
    for i in data:
        frequency[i] += 1
    return frequency

def huffman_tree(frequency):
    heap = [[weight, [symbol, ""]] for symbol, weight in frequency.items()]
    heapq.heapify(heap)
    while len(heap) > 1:
        lo = heapq.heappop(heap)
        hi = heapq.heappop(heap)
        for pair in lo[1:]:
            pair[1] = '0' + pair[1]
        for pair in hi[1:]:
            pair[1] = '1' + pair[1]
        heapq.heappush(heap, [lo[0] + hi[0]] + lo[1:] + hi[1:])
    return sorted(heapq.heappop(heap)[1:], key=lambda p: (len(p[-1]), p))

def huffman_code(tree):
    huffman_code = {}
    for pair in tree:
        huffman_code[pair[0]] = pair[1]
    return huffman_code

def compress(data, huffman_code):
    compressed_data = ""
    for char in data:
        compressed_data += huffman_code[char]
    return compressed_data

def decompress(compressed_data, huffman_code):
    reverse_huffman_code = {v: k for k, v in huffman_code.items()}
    decompressed_data = ""
    temp = ""
    for bit in compressed_data:
        temp += bit
        if temp in reverse_huffman_code:
            decompressed_data += reverse_huffman_code[temp]
            temp = ""
    return decompressed_data

# Main function
if __name__ == "__main__":
    data = "the quick brown fox jumps over the lazy dog"
    frequency = calculate_frequency(data)
    tree = huffman_tree(frequency)
    huffman_code = huffman_code(tree)
    compressed_data = compress(data, huffman_code)
    decompressed_data = decompress(compressed_data, huffman_code)
    print("Original: ", data)
    print("Compressed: ", compressed_data)
    print("Decompressed: ", decompressed_data)
```

