func transposeAndSortMatrix(matrix: [[Double]]) -> [[Double]] {
    // Transpose the matrix
    var transposed: [[Double]] = Array(repeating: Array(repeating: 0.0, count: matrix.count), count: matrix[0].count)
    for i in 0..<matrix.count {
