    if (arr.length < 2) {
        console.log("Array does not contain enough elements.");
        return null; // Or adjust based on how you wish to handle this scenario
    }

    let max = Number.MIN_SAFE_INTEGER;
    let secondMax = Number.MIN_SAFE_INTEGER;

