import java.util.HashMap;
import java.util.Map;

public class Fibonacci {

    static Map<Integer, Long> memo = new HashMap<>();

    public static long fibonacci(int n) {
        if (n <= 1) {
            return n;
        }
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        long result = fibonacci(n - 1) + fibonacci(n - 2);
        memo.put(n, result);
        return result;
    }

    public static void main(String[] args) {
        int n = 10;

        long startTime = System.nanoTime();
        System.out.println("Fibonacci Sequence using Recursion:");
        for (int i = 0; i < n; i++) {
            System.out.print(fibonacci(i) + " ");
        }
        long endTime = System.nanoTime();
        long timeComplexity = endTime - startTime;
        System.out.println("\nTime Complexity of Recursive Fibonacci: " + timeComplexity + " ns");

        // Clear memoization map
        memo.clear();

        startTime = System.nanoTime();
        System.out.println("\nFibonacci Sequence using Recursion with Memoization:");
        for (int i = 0; i < n; i++) {
            System.out.print(fibonacci(i) + " ");
        }
        endTime = System.nanoTime();
        timeComplexity = endTime - startTime;
        System.out.println("\nTime Complexity of Recursive Fibonacci with Memoization: " + timeComplexity + " ns");
    }
}
```

