    Node tail;

    public DoublyLinkedList() {
        this.head = null;
        this.tail = null;
    }

    public void insertSorted(int data) {
        Node newNode = new Node(data);

        if (head == null) {
            head = newNode;
            tail = newNode;
        } else if (data <= head.data) {
            newNode.next = head;
            head.prev = newNode;
            head = newNode;
        } else if (data >= tail.data) {
