```python
def maxSumPath(grid, k):
    N = len(grid)
    dp = [[[-float('inf')]*(k+1) for _ in range(N)] for _ in range(N)]

    def solve(i, j, k):
        if i < 0 or j < 0 or k < 0:
            return -float('inf')
        if k == 0:
            return grid[i][j]
        if dp[i][j][k] != -float('inf'):
            return dp[i][j][k]

        dp[i][j][k] = max(solve(i-1, j, k-1), solve(i, j-1, k-1)) + grid[i][j]
        return dp[i][j][k]

    answer = []
    while k > 0:
        if i > 0 and solve(i-1, j, k-1) >= solve(i, j-1, k-1):
            answer.append(grid[i][j])
            i -= 1
        else:
            answer.append(grid[i][j])
            j -= 1
        k -= 1
    return answer[::-1]
```

