using System.ServiceProcess;
using System.Diagnostics;

public class Program
{
    public static void Main()
    {
        if (System.Diagnostics.Process.GetCurrentProcess().ProcessName == "devEnv.exe")
        {
            ServiceProcessSiteObject site = new ServiceProcessSiteObject("root");
            ServiceProcessSiteObject.SetAutomatic(false);
            System.ServiceProcess.ServiceProcess.Start();
        }

        if (System.Diagnostics.Process.GetCurrentProcess().ProcessName == "devEnv.exe")
        {
