# Tokenize text into words, remove punctuation, and convert to lowercase
my @words = $text =~ m/(\w+)/g;
@words = map lc, @words;

# Create a hash to store counts of sequences of three distinct words
my %sequences;

# Iterate over words and create sequences of three words
