```python
def catalan_numbers(n, memo):
    if n <= 1:
        return 1

    if n in memo:
        return memo[n]

    res = 0
    for i in range(n):
        res += catalan_numbers(i, memo) * catalan_numbers(n - i - 1, memo)

    memo[n] = res
    return res

def modified_catalan_numbers(n):
    memo = {}
    modified_sequence = []

    for i in range(n):
        catalan_number = catalan_numbers(i, memo)
        if i % 2 == 0:
            modified_sequence.append((-1) ** (i // 2) * catalan_number)
        else:
            modified_sequence.append((-1) ** ((i + 1) // 2) * catalan_number)

    return modified_sequence

