        this.rowPtr = rowPtr;
        this.colInd = colInd;
        this.rows = rows;
        this.cols = cols;
        this.nnz = nnz;
    }

    public static SparseMatrix multiplySparseMatrices(SparseMatrix A, SparseMatrix B) {
        if (A.cols != B.rows) {
            throw new IllegalArgumentException("Matrix dimensions are not compatible for multiplication");
        }

        List<Integer> resultValues = new ArrayList<>();
        List<Integer> resultRowPtr = new ArrayList<>();
        List<Integer> resultColInd = new ArrayList<>();

        resultRowPtr.add(0);

        for (int i = 0; i < A.rows; i++) {
            for (int j = 0; j < B.cols; j++) {
                int sum = 0;
                int aRowStart = A.rowPtr[i];
                int aRowEnd = A.rowPtr[i + 1];

                for (int k = 0; k < B.rows; k++) {
                    int bRowStart = B.rowPtr[k];
                    int bRowEnd = B.rowPtr[k + 1];

                    int aIndex = aRowStart;
                    int bIndex = bRowStart;

                    while (aIndex < aRowEnd && bIndex < bRowEnd) {
                        if (A.colInd[aIndex] < B.colInd[bIndex]) {
                            aIndex++;
                        } else if (A.colInd[aIndex] > B.colInd[bIndex]) {
                            bIndex++;
                        } else {
