        int[] resultRowPtrArr = resultRowPtr.stream().mapToInt(Integer::intValue).toArray();
        int[] resultColIndArr = resultColInd.stream().mapToInt(Integer::intValue).toArray();

        return new SparseMatrix(resultValuesArr, resultRowPtrArr, resultColIndArr, A.rows, B.cols, resultValuesArr.length);
    }
